11	
12	class OperationStreamFrameBroadcaster
13	{
14	    /**
15	     * @param  array<string, mixed>  $frame
16	     */
17	    public function broadcast(string $channel, array $frame): void
18	    {
19	        $appId = Config::string('orbit.operations.reverb.app_id');
20	        $appKey = Config::string('orbit.operations.reverb.app_key');
21	        $appSecret = Config::string('orbit.operations.reverb.app_secret');
22	        $host = Config::string('orbit.operations.reverb.host');
23	        $port = Config::integer('orbit.operations.reverb.port');
24	        $scheme = Config::string('orbit.operations.reverb.scheme');
25	        $timeoutSeconds = Config::integer('orbit.operations.reverb.timeout_seconds', 2);
26	
27	        $body = [
28	            'name' => 'operation.stream.frame',
29	            'channel' => $channel,
30	            'data' => json_encode($frame, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR),
31	        ];
32	
33	        $encodedBody = json_encode($body, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
34	        $path = "/apps/{$appId}/events";
35	        $query = [
36	            'auth_key' => $appKey,
37	            'auth_timestamp' => (string) Carbon::now()->timestamp,
38	            'auth_version' => '1.0',
39	            'body_md5' => md5($encodedBody),
40	        ];
41	
42	        ksort($query);
43	
44	        $signaturePayload = "POST\n{$path}\n".http_build_query($query, '', '&', PHP_QUERY_RFC3986);
45	        $query['auth_signature'] = hash_hmac('sha256', $signaturePayload, $appSecret);
46	
47	        $url = "{$scheme}://{$host}:{$port}{$path}?".http_build_query($query, '', '&', PHP_QUERY_RFC3986);
48	
49	        $response = Http::timeout($timeoutSeconds)
50	            ->asJson()
51	            ->post($url, $body);
52	
53	        if ($response->failed()) {
54	            throw new RuntimeException('Failed to publish operation stream frame to the operations Reverb service.');
55	        }
56	    }
57	}
