5	namespace App\Services;
6	
7	use App\Exceptions\GatewayApiException;
8	use Illuminate\Http\Client\ConnectionException;
9	use Illuminate\Http\Client\PendingRequest;
10	use Illuminate\Http\Client\Response;
11	use Illuminate\Support\Facades\Http;
12	use Orbit\Core\Progress\ForkedFrameTicker;
13	use Orbit\Core\Progress\ProgressEvent;
14	use Orbit\Core\Progress\ProgressEventDecoder;
15	use Orbit\Core\Progress\ProgressEventDecodingFailed;
16	use Orbit\Core\Progress\ProgressEventType;
17	use Orbit\Core\Progress\StreamIdleReader;
18	use Psr\Http\Message\StreamInterface;
19	use Throwable;
20	
21	class GatewayOperationEventStreamClient
22	{
23	    private const int ReadBytes = 8192;
24	
25	    public function __construct(
26	        private readonly ?string $baseUrl,
27	        private readonly int $timeout,
28	        private readonly ?string $caPemPath = null,
29	    ) {}
30	
31	    /**
32	     * @param  callable(ProgressEventType, array<string, mixed>, int|null): void  $onEvent
33	     * @return array{type: ProgressEventType, payload: array<string, mixed>}|null
34	     */
35	    public function replay(string $eventsUrl, ?int $lastEventId, callable $onEvent): ?array
36	    {
37	        if (ForkedFrameTicker::hasIdleCallback() && function_exists('curl_multi_init')) {
38	            return $this->replayWithCurlIdleTicks($eventsUrl, $lastEventId, $onEvent);
39	        }
40	
41	        try {
42	            $response = $this->openStreamResponse($eventsUrl, $lastEventId);
43	        } catch (ConnectionException $exception) {
44	            throw $this->classifyNetworkError($exception);
45	        }
46	
47	        if ($response->failed()) {
48	            throw GatewayApiException::httpError($response->status(), $response->body());
49	        }
50	
51	        return $this->processResponseStream($response->toPsrResponse()->getBody(), $onEvent);
52	    }
53	
54	    private function openStreamResponse(string $eventsUrl, ?int $lastEventId): Response
55	    {
56	        return $this->pendingRequest($lastEventId)->get('/'.ltrim($eventsUrl, '/'));
57	    }
58	
59	    private function pendingRequest(?int $lastEventId): PendingRequest
60	    {
61	        return Http::baseUrl($this->normalizedBaseUrl())
62	            ->withHeaders($this->headers($lastEventId))
63	            ->timeout($this->timeout)
64	            ->withOptions($this->streamOptions());
65	    }
66	
67	    /**
68	     * @param  callable(ProgressEventType, array<string, mixed>, int|null): void  $onEvent
69	     * @return array{type: ProgressEventType, payload: array<string, mixed>}|null
70	     */
71	    private function replayWithCurlIdleTicks(string $eventsUrl, ?int $lastEventId, callable $onEvent): ?array
72	    {
73	        $curl = curl_init($this->absoluteUrl($eventsUrl));
74	
75	        if ($curl === false) {
76	            throw $this->classifyNetworkError(new ConnectionException('Unable to initialize operation event stream.'));
77	        }
78	
79	        $multi = curl_multi_init();
80	
81	        $decoder = new ProgressEventDecoder;
82	        $frameBuffer = '';
83	        $bodyBuffer = '';
84	        $terminal = null;
85	        $failure = null;
86	
87	        curl_setopt_array($curl, [
88	            CURLOPT_HTTPGET => true,
89	            CURLOPT_HTTPHEADER => $this->curlHeaders($lastEventId),
90	            CURLOPT_TIMEOUT => $this->timeout,
91	            CURLOPT_CONNECTTIMEOUT => $this->timeout,
92	            CURLOPT_HEADER => false,
93	            CURLOPT_RETURNTRANSFER => false,
94	            CURLOPT_WRITEFUNCTION => function ($curl, string $chunk) use (
95	                $decoder,
96	                &$frameBuffer,
97	                &$bodyBuffer,
98	                &$terminal,
99	                &$failure,
100	                $onEvent,
101	            ): int {
102	                $bodyBuffer .= $chunk;
103	
104	                if ($terminal !== null) {
105	                    return strlen($chunk);
106	                }
107	
108	                try {
109	                    $frameBuffer .= $chunk;
110	                    $terminal = $this->processCompleteFrames($decoder, $frameBuffer, $onEvent);
111	                } catch (Throwable $exception) {
112	                    $failure = $exception;
113	
114	                    return 0;
115	                }
116	
117	                return strlen($chunk);
118	            },
119	        ]);
120	
121	        if (is_string($this->caPemPath) && $this->caPemPath !== '' && is_file($this->caPemPath)) {
122	            curl_setopt($curl, CURLOPT_CAINFO, $this->caPemPath);
123	        }
124	
125	        curl_multi_add_handle($multi, $curl);
126	
127	        try {
128	            $running = null;
129	
130	            do {
131	                do {
132	                    $multiStatus = curl_multi_exec($multi, $running);
133	                } while ($multiStatus === CURLM_CALL_MULTI_PERFORM);
134	
135	                if ($multiStatus !== CURLM_OK) {
136	                    throw $this->classifyNetworkError(new ConnectionException(curl_multi_strerror($multiStatus)));
137	                }
138	
139	                if ($failure instanceof Throwable || $terminal !== null) {
140	                    break;
141	                }
142	
143	                if ($running > 0) {
144	                    ForkedFrameTicker::invokeIdleCallback();
145	
146	                    if (curl_multi_select($multi, 0.0) === -1) {
147	                        usleep(250);
148	                    }
149	
150	                    usleep(ForkedFrameTicker::idleIntervalMicroseconds());
151	                }
