13	class GatewayOperationFollower
14	{
15	    public function __construct(
16	        private readonly GatewayOperationEventStreamClient $events,
17	        private readonly int $reconnectSleepMs = 500,
18	        private readonly int $maxEmptyReplays = 0,
19	        private readonly int $maxTransientFailures = 120,
20	    ) {}
21	
22	    /**
23	     * @param  callable(ProgressEventType, array<string, mixed>): void  $onEvent
24	     * @return array{type: ProgressEventType, payload: array<string, mixed>}
25	     */
26	    public function follow(string $eventsUrl, callable $onEvent): array
27	    {
28	        $lastEventId = null;
29	        $seenEventIds = [];
30	        $emptyReplays = 0;
31	        $transientFailures = 0;
32	
33	        while (true) {
34	            $sawEvent = false;
35	
36	            try {
37	                $terminal = $this->events->replay(
38	                    $eventsUrl,
39	                    $lastEventId,
40	                    function (ProgressEventType $type, array $payload, ?int $eventId) use (
41	                        &$lastEventId,
42	                        &$seenEventIds,
43	                        &$sawEvent,
44	                        $onEvent,
45	                    ): void {
46	                        if ($eventId !== null) {
47	                            if (isset($seenEventIds[$eventId])) {
48	                                return;
49	                            }
50	
51	                            $seenEventIds[$eventId] = true;
52	                            $lastEventId = max($lastEventId ?? 0, $eventId);
53	                        }
54	
55	                        $sawEvent = true;
56	                        $onEvent($type, $payload);
57	                    },
58	                );
59	                $transientFailures = 0;
60	            } catch (GatewayApiException $exception) {
61	                if (! $this->shouldRetry($exception) || $transientFailures >= $this->maxTransientFailures) {
62	                    throw $exception;
63	                }
64	
65	                $transientFailures++;
66	                $this->sleepBeforeReconnect();
67	
68	                continue;
69	            }
70	
71	            if ($terminal !== null) {
72	                return $terminal;
73	            }
74	
75	            $emptyReplays = $sawEvent ? 0 : $emptyReplays + 1;
76	
77	            if ($this->maxEmptyReplays > 0 && $emptyReplays >= $this->maxEmptyReplays) {
78	                throw GatewayApiException::streamClosedBeforeTerminal(
79	                    new RuntimeException('Operation event replay did not reach a terminal frame.'),
80	                );
81	            }
82	
83	            $this->sleepBeforeReconnect();
84	        }
85	    }
86	
87	    private function shouldRetry(GatewayApiException $exception): bool
88	    {
89	        if (
90	            $exception->failureKind() === GatewayApiFailureKind::Network
91	            || $exception->failureKind() === GatewayApiFailureKind::WireguardUnreachable
92	        ) {
93	            return true;
94	        }
95	
96	        if ($exception->failureKind() !== GatewayApiFailureKind::Http) {
97	            return false;
98	        }
99	
100	        return in_array($exception->statusCode(), [502, 503, 504], true);
101	    }
102	
103	    private function sleepBeforeReconnect(): void
104	    {
105	        if ($this->reconnectSleepMs <= 0) {
106	            return;
107	        }
108	
109	        $remainingMicroseconds = $this->reconnectSleepMs * 1000;
110	
111	        while ($remainingMicroseconds > 0) {
112	            ForkedFrameTicker::invokeIdleCallback();
113	
114	            $sleepMicroseconds = min($remainingMicroseconds, ForkedFrameTicker::idleIntervalMicroseconds());
115	            usleep($sleepMicroseconds);
116	
117	            $remainingMicroseconds -= $sleepMicroseconds;
118	        }
119	    }
120	}
